CHROM_LENGTHS = {chrom.replace(".", "_"): length for chrom, length in CHROM_LENGTHS.items()}
MUTATION_RATE = 2.5e-9

def main():
    pop = sys.argv[1]
    vcf_path = os.path.expanduser(POP_VCFS[pop])
    samples = POP_SAMPLES[pop]

    contigs = [
        phlash.contig(vcf_path, samples=samples, region=f"{chrom}:1-{length}")
        for chrom, length in CHROM_LENGTHS.items()
    ]
    test_data = contigs[0]
    train_data = contigs[1:]

    print(f"Fitting {pop} ({len(train_data)} train contigs)...", flush=True)
    res = phlash.fit(train_data, test_data=test_data, mutation_rate=MUTATION_RATE)

    with open(f"phlash_results_{pop}.pkl", "wb") as f:
        pickle.dump(res, f)
    print(f"Done: {pop}", flush=True)

if __name__ == "__main__":
    main()
